head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _7 : 기타 옵션(optionParam, msaName). description 은 분리 샘플 공통.
//  ★ 두 옵션 모두 확인용 getter 가 없으므로 CSV 다운로드 전송 직전의 요청 URL / 전송 파라미터를 가로채어 검증한다.
scwin.tData = {
    "description" : "[gridView > M > saveCSV]<br/>GridView 컴포넌트의 데이터를 CSV 형식의 파일로 다운로드합니다.",
    "validation" : [
        "optionParam(선택) 파라미터로 파일 암호화(DRM) 연계 시 사용자 정의 Class 에 HashMap 인자로 전달할 값을 설정합니다.",
        "optionParam(선택) 파라미터는 서버에서 'optionParam' 키로 참조됩니다.",
        "optionParam(선택) 파라미터를 생략하면 기본값인 빈 문자열로 동작합니다.",
        "msaName(선택) 파라미터로 MSA 기능을 사용하는 경우 적용할 MSA 서버의 이름을 설정합니다.",
        "msaName(선택) 파라미터가 지정된 경우 해당 MSA 서버의 경로가 자동으로 URL 에 추가됩니다.",
        "msaName(선택) 파라미터를 생략하면 기본값인 빈 문자열로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · saveCSV 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- optionParam / msaName 은 확인용 getter 가 없으므로 CSV 다운로드 전송 직전의 요청 URL 과 전송 파라미터를 읽어 확인함\n[절차]\n1. par 옵션(optionParam / msaName) 값을 선택한다\n2. saveCSV 버튼을 클릭한다\n[확인]\n- optionParam 은 전송 파라미터 출력으로 확인 - 미설정 시 value= 가 빈값, optionParamTest 설정 시 value=optionParamTest 로 대비되고 전송 키 이름(hashkey)이 optionParam 인 것으로 서버에서 참조되는 키를 확인\n- msaName 은 전송 요청 URL 로 확인 - 미설정 시 /websquare/xmlToCSV.wq, msa_server(config.xml 등록명) 설정 시 http://192.168.100.250:8080 MSA 서버 경로가 자동으로 추가되는 것을 확인\n- msa_server 는 로컬에서 실제 응답하지 않으므로 다운로드 성공 여부가 아닌 요청 URL 로만 판정한다"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 saveCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
scwin.buildOptions = function () {
    let options = {};
    let v;

    v = par_optionParam.getValue();
    if (v !== "") options.optionParam = v;

    v = par_msaName.getValue();
    if (v !== "") options.msaName = v;

    return options;
}



// saveCSV 실행
//  · saveCSV 의 전송 폼은 submit 직후 DOM 에서 제거되고, msaName 지정 시에는 XHR 로 전송되므로
//    전송 직전에 요청 URL 과 전송 파라미터를 가로채어 확인한다. (실제 전송은 그대로 수행)
scwin.btn_saveCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objSend = { "url" : "", "body" : "" };

    let fnFormSubmit = HTMLFormElement.prototype.submit;
    let fnXhrOpen = XMLHttpRequest.prototype.open;
    let fnXhrSend = XMLHttpRequest.prototype.send;

    HTMLFormElement.prototype.submit = function () {
        let objValue = this.querySelector("input[name='xmlValue']");
        objSend.url = this.getAttribute("action") || "";
        objSend.body = (objValue === null) ? "" : objValue.value;
        return fnFormSubmit.apply(this, arguments);
    };
    XMLHttpRequest.prototype.open = function (strMethod, strUrl) {
        objSend.url = strUrl;
        return fnXhrOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function (strData) {
        objSend.body = strData || "";
        return fnXhrSend.apply(this, arguments);
    };

    try {
        target1.saveCSV(scwin.buildOptions());
    } finally {
        HTMLFormElement.prototype.submit = fnFormSubmit;
        XMLHttpRequest.prototype.open = fnXhrOpen;
        XMLHttpRequest.prototype.send = fnXhrSend;
    }

    // 폼 전송 시 URL 뒤에 붙는 캐시 회피용 suffix 는 제외하고 출력한다.
    let strUrl = objSend.url.replace(/[?&]suffix=[^&]*/, "");
    let arrParam = objSend.body.match(/<data hashkey='optionParam'[^>]*\/>/);

    bottom.setReturnValue("전송 요청 URL : " + strUrl);
    bottom.setReturnValue("전송 파라미터 : " + ((arrParam === null) ? "" : arrParam[0]));
}
